package me.ag2s.epublib.epub
import java.io.*
import javax.xml.parsers.*
import org.xml.sax.*
import org.xmlpull.v1.*
object EpubProcessorSupport { @JvmField val documentBuilderFactory: DocumentBuilderFactory = DocumentBuilderFactory.newInstance().apply { setNamespaceAware(true); setValidating(false) }; @JvmStatic fun createXmlSerializer(out: OutputStream): XmlSerializer? = createXmlSerializer(OutputStreamWriter(out,"UTF-8")); @JvmStatic fun createXmlSerializer(out: Writer): XmlSerializer? = try { val factory=XmlPullParserFactory.newInstance(); factory.setValidating(true); val serializer=factory.newSerializer(); serializer.setFeature("http://xmlpull.org/v1/doc/features.html#indent-output",true); serializer.setOutput(out); serializer } catch(e:Exception) { e.printStackTrace(); null }; @JvmStatic fun getEntityResolver(): EntityResolver = EntityResolverImpl(); @JvmStatic fun createDocumentBuilder(): DocumentBuilder? = try { documentBuilderFactory.newDocumentBuilder().apply { setEntityResolver(getEntityResolver()) } } catch(e:ParserConfigurationException) { e.printStackTrace(); null }; class EntityResolverImpl: EntityResolver { private var previousLocation: String?=null; override fun resolveEntity(publicId:String?,systemId:String):InputSource { val path=if(systemId.startsWith("http:")){ val url=java.net.URL(systemId); ("dtd/"+url.host+url.path).also { previousLocation=it.substring(0,it.lastIndexOf('/')) } }else previousLocation+systemId.substring(systemId.lastIndexOf('/')); val loader=javaClass.classLoader!!; if(loader.getResource(path)==null) throw RuntimeException("remote resource is not cached : [$systemId] cannot continue"); return InputSource(loader.getResourceAsStream(path)) } } }
